import fs from 'node:fs/promises';import{db}from'./reply-runtime-20261015.mjs';
const dir='artifacts/reply-review-20261019-weekend';const results=JSON.parse(await fs.readFile(dir+'/send-results.json')).results.filter(r=>r.state==='accepted');const checks=[];
for(const r of results){const [events,touches]=await Promise.all([db('crm_sms_provider_events',{provider_message_id:'eq.'+r.sid.replace('telnyx:',''),event_type:'eq.message.finalized',order:'occurred_at.desc',limit:'10'}),db('market_touches',{'metadata->>twilioSid':'eq.'+r.sid,direction:'eq.outbound'})]);checks.push({...r,touches:touches.length,delivery:events.find(e=>e.status==='delivered')?.status||events[0]?.status||'awaiting_final_receipt'});if(touches.length!==1)throw Error('Receipt mismatch '+r.name);}
await fs.writeFile(dir+'/delivery-verification.json',JSON.stringify({at:new Date().toISOString(),checks},null,2));console.log(JSON.stringify({accepted:checks.length,cards:checks.filter(c=>c.card).length,delivery:checks.reduce((a,c)=>(a[c.delivery]=(a[c.delivery]||0)+1,a),{})}));
const recent=await db('market_touches',{direction:'eq.inbound',created_at:'gte.2026-10-19T16:32:00Z',order:'created_at.asc,id.asc',limit:'1000'});if(recent.length===1000)throw Error('Pagination needed');await fs.writeFile(dir+'/new-inbound-during-review.json',JSON.stringify(recent,null,2));console.log(JSON.stringify({new_window_inbound:recent.length}));
